-- 轨道交通智能运维数据智能体：模拟业务数据
-- 生成日期：2026-09-15
-- 注意：本文件会清空 line / vehicle / device / fault_record / alarm_record / vehicle_daily_health 六张表后重新写入模拟数据。
-- 数据完全为项目演示用合成数据，不代表真实线路或真实车辆运营情况。
-- 健康度由当日设备基线、故障数量/严重故障数量、报警数量/严重报警数量综合计算。

SET NAMES utf8mb4;
USE railway_agent;
SET FOREIGN_KEY_CHECKS = 0;

TRUNCATE TABLE vehicle_daily_health;
TRUNCATE TABLE alarm_record;
TRUNCATE TABLE fault_record;
TRUNCATE TABLE device;
TRUNCATE TABLE vehicle;
TRUNCATE TABLE line;

SET FOREIGN_KEY_CHECKS = 1;

START TRANSACTION;





















































COMMIT;

-- 导入完成后的快速检查
SELECT 'line' AS table_name, COUNT(*) AS row_count FROM line
UNION ALL SELECT 'vehicle', COUNT(*) FROM vehicle
UNION ALL SELECT 'device', COUNT(*) FROM device
UNION ALL SELECT 'fault_record', COUNT(*) FROM fault_record
UNION ALL SELECT 'alarm_record', COUNT(*) FROM alarm_record
UNION ALL SELECT 'vehicle_daily_health', COUNT(*) FROM vehicle_daily_health;

SELECT MIN(stat_date) AS health_start_date,
       MAX(stat_date) AS health_end_date,
       ROUND(AVG(health_score), 2) AS avg_health_score
FROM vehicle_daily_health;

SELECT health_level, COUNT(*) AS days_count
FROM vehicle_daily_health
GROUP BY health_level
ORDER BY MIN(health_score) DESC;
